import re
import os
from moler.util.moler_test import MolerTest  # type: ignore
from time import ctime


class ProcdumpParser(object):
    def __init__(self, procdump_dir):
        """
        :param procdump_dir: path to directory containing procdump files
        """
        self.procdump_dir = procdump_dir
        self.procdump_files = []
        self.data = {"systime": [],
                     "diskspace": {},  # to store procdump in dictionary
                     "meminfo": {},
                     "interrupts": {},
                     "procinfo": {},
                     "cpu_data": {},
                     "cpu_info": {}}
        self.json_data = {"cpu_info_overall_json_format": {},
                          "meminfo_json_format": [],  # '_json_format' means format ready to insert to database json
                          "diskspace_used_json_format": [],
                          "interrupts_json_format": {},
                          "cpu_load_general_view_json_format": [],
                          "cpu_info_details_json_format": []}

    def parse(self):
        """
        start parsing procdump files process
        """
        self._analyze_all_procdump_files()
        # data to database.json
        self._prepare_meminfo_json_format()
        self._prepare_diskspaceinfo_json_format()
        self._prepare_interrupts_json_format()
        self._prepare_cpu_usage_info()

    def get(self, table_name):
        """
        :param table_name: name of table from self.data e.g. table_name="systime"
        :return: return chosen data from self.data e.g. self.data["systime"]
        """
        return self.data[table_name]

    def get_data(self):
        """
        :return: return whole self.data
        """
        return self.data

    def get_detail(self, data_type, key, element):
        """
        :param data_type: statistics type from self.data eg. data_type="cpu_data"
        :param key: accurated parameter from data_type e.g. self.data["diskspace"]["CPU"]
        :param element:
        :return:
        """
        return self.data[data_type][key][element]

    def _analyze_dumps(self, procdump_file):
        file_path = os.path.join(self.procdump_dir, procdump_file)
        try:
            with open(file_path, 'r') as input_procdump_file:
                for line in input_procdump_file:
                    try:
                        self._analyze_procdump_line(line, input_procdump_file)
                    except (IndexError, KeyError):
                        print("ProcdumpParser: Errors during parsing dumps")  # noqa: T201
        except IOError:
            print("ProcdumpParser: File not found: " + str(file_path))  # noqa: T201

    def _select_files_for_analysis(self):
        try:
            return sorted(os.listdir(self.procdump_dir))
        except IOError:
            print("ProcumpParser: Directory not found: " + str(self.procdump_dir))  # noqa: T201
            return []

    def _analyze_procdump_line(self, line, input_procdump_file):
        if "@systime {" in line:
            self._analyze_systime(input_procdump_file)
        if "@diskspace {" in line:
            self._analyze_diskspace(input_procdump_file)
        if "@meminfo {" in line:
            self._analyze_meminfo(input_procdump_file)
        if "@interrupts {" in line:
            self._analyze_interrupts(input_procdump_file)
        if "@stat {" in line:
            self._analyze_proc_usage_info(input_procdump_file)

    def _analyze_all_procdump_files(self):
        self.procdump_files = self._select_files_for_analysis()
        for procdump_file in self.procdump_files:
            self._analyze_dumps(procdump_file)

    def _analyze_systime(self, input_procdump_file):
        for line in input_procdump_file:
            if "}@" in line:
                return 0
            line = ctime(int(line))
            self.data["systime"].append(line.strip())

    def _analyze_diskspace(self, input_procdump_file):
        for line in input_procdump_file:
            if "}@" in line:
                return 0
            diskspace_columns = re.split(r"\s+", line.replace("%", ""))
            try:
                if diskspace_columns[5]:
                    self._fulfill_diskspace_data(diskspace_columns)
            except IndexError:
                print("ProcdumpParser: Unable to analyze diskspace info")  # noqa: T201

    def _fulfill_diskspace_data(self, diskspace_data):
        if diskspace_data[5] != 'Mounted':
            if diskspace_data[5] not in self.data["diskspace"]:
                self.data['diskspace'][diskspace_data[5]] = \
                    {"Filesystem": [], "OneKBlock": [], "Used": [], "Available": [], "Use": []}
            if diskspace_data[5] in self.data["diskspace"]:
                diskspace_parameters = self.data["diskspace"][diskspace_data[5]]
                diskspace_parameters["Filesystem"].append(diskspace_data[0])
                diskspace_parameters["OneKBlock"].append(diskspace_data[1])
                diskspace_parameters["Used"].append(diskspace_data[2])
                diskspace_parameters["Available"].append(diskspace_data[3])
                diskspace_parameters["Use"].append(diskspace_data[4])
                self.data['diskspace'][diskspace_data[5]].update(diskspace_parameters)

    def _analyze_meminfo(self, input_procdump_file):
        selected_params = ['Active', 'Buffers', 'Cached', 'Committed_AS', 'Inactive', 'MemFree', 'SUnreclaim', 'Shemem']
        for line in input_procdump_file:
            if "}@" in line:
                return 0
            meminfo_values = re.split(r"\s+", line)
            meminfo_param = meminfo_values[0]
            if meminfo_param.replace(':', '') in selected_params:
                if meminfo_param not in self.data["meminfo"]:
                    self.data["meminfo"][meminfo_param] = []
                if meminfo_param in self.data["meminfo"]:
                    self.data["meminfo"][meminfo_param].append(meminfo_values[1])

    def _analyze_interrupts(self, input_procdump_file):
        for line in input_procdump_file:
            if "}@" in line:
                return 0
            try:
                self._get_interrupts_cores_info(line)
                if self.cpu_cores:
                    self._fulfill_interrupts_data(line)
            except (NameError, IndexError):
                print("ProcdumpParser: Unable to analyze interrupts")  # noqa: T201

    def _get_interrupts_cores_info(self, line):
        if re.search(r"^\s+CPU\d+", line):
            self.cpu_cores = []
            for cpu in re.split(r"\s+", line.strip()):
                if "CPU" in cpu:
                    self.cpu_cores.append(re.match(r"CPU(\d+)", cpu).group(1))

    def _prepare_interrupts_names(self, line):
        interrupts_data = re.split(r"\s+", line.strip())
        interrupt_name = "".join(interrupts_data[len(self.cpu_cores) + 1:])
        return interrupts_data, interrupt_name

    def _fulfill_interrupts_data(self, line):
        interrupts_data, interrupt_name = self._prepare_interrupts_names(line)
        if interrupt_name == '0':
            return 0
        self._prepare_interrupts_data_in_dict_format(interrupts_data, interrupt_name)

    def _prepare_interrupts_data_in_dict_format(self, interrupts_data, interrupt_name):
        if len(interrupts_data) > len(self.cpu_cores):
            if interrupt_name not in self.data["interrupts"]:
                self.data["interrupts"][interrupt_name] = {}
            for index, cpu_core in enumerate(self.cpu_cores):
                if cpu_core not in self.data["interrupts"][interrupt_name]:
                    self.data["interrupts"][interrupt_name][cpu_core] = []
                if cpu_core in self.data["interrupts"][interrupt_name]:
                    self.data["interrupts"][interrupt_name][cpu_core].append(interrupts_data[index + 1])

    def _analyze_proc_usage_info(self, input_procdump_file):
        for line in input_procdump_file:
            if "}@" in line:
                return 0
            matched_line = self._check_regex(line)
            if matched_line:
                try:
                    self._fulfill_proc_usage_info_data(matched_line)
                except IndexError:
                    print("ProcdumpParser: Unable to analyze CPU usage")  # noqa: T201

    @staticmethod
    def _check_regex(line):
        # cpu1 119169 0 136983 47057978 2 0 263141 0 0 0
        return re.match(r"cpu(?P<CPU_NUMBER>\d*)\s+(?P<user>\d+)\s+(?P<nice>\d+)\s+(?P<sys>\d+)"
                        r"\s+(?P<idle>\d+)\s+(?P<iowat>\d+)\s+(?P<irq>\d+)\s+(?P<softirq>\d+)\s+"
                        r"(?P<total_comp_1>\d+)\s+(?P<total_comp_2>\d+)\s+(?P<total_comp_3>\d+)", line)

    def _fulfill_empty_cpu_parameters(self, cpu_id):
        self.data["cpu_data"][cpu_id] = {
            "total": [], "user": [], "nice": [], "sys": [],
            "idle": [], "iowat": [], "irq": [], "softirq": []}
        self.data["cpu_info"][cpu_id] = {
            "total": [], "user": [], "nice": [], "sys": [],
            "idle": [], "iowat": [], "irq": [], "softirq": [], "usage": []}

    @staticmethod
    def _calculate_total_cpu(matched_line):
        total = int(matched_line.group("user")) + int(matched_line.group("nice")) + int(matched_line.group("sys")) \
            + int(matched_line.group("idle")) + int(matched_line.group("iowat")) + int(matched_line.group("irq")) \
            + int(matched_line.group("softirq")) + int(matched_line.group("total_comp_1")) \
            + int(matched_line.group("total_comp_2")) + int(matched_line.group("total_comp_3"))
        return total

    def _fulfill_cpu_data(self, cpu_id, matched_line):
        self.data["cpu_data"][cpu_id]["user"].append(matched_line.group("user"))
        self.data["cpu_data"][cpu_id]["nice"].append(matched_line.group("nice"))
        self.data["cpu_data"][cpu_id]["sys"].append(matched_line.group("sys"))
        self.data["cpu_data"][cpu_id]["idle"].append(matched_line.group("idle"))
        self.data["cpu_data"][cpu_id]["iowat"].append(matched_line.group("iowat"))
        self.data["cpu_data"][cpu_id]["irq"].append(matched_line.group("irq"))
        self.data["cpu_data"][cpu_id]["softirq"].append(matched_line.group("softirq"))
        total = self._calculate_total_cpu(matched_line)
        self.data["cpu_data"][cpu_id]["total"].append(total)

    def _fulfill_proc_usage_info_data(self, matched_line):
        cpu_id = matched_line.group("CPU_NUMBER").upper()
        label = "CPU "
        if cpu_id == "":
            cpu_id = "total"
        else:
            cpu_id = "{}{}".format(label, cpu_id)
        if cpu_id not in self.data["cpu_data"]:
            self._fulfill_empty_cpu_parameters(cpu_id)
        if cpu_id in self.data["cpu_data"]:
            self._fulfill_cpu_data(cpu_id, matched_line)

    def _prepare_diff_total(self):
        for cpu_id in self.data["cpu_data"].keys():
            for index in range(0, len(self.data["cpu_data"][cpu_id]["total"]) - 1):
                if index > 0:
                    diff_total = self._calculate_diff_total(cpu_id, index)
                    self._prepare_usage_cpu_info(cpu_id, diff_total, index)
                else:
                    for cpu_key in self.data["cpu_data"][cpu_id]:
                        self.data["cpu_info"][cpu_id][cpu_key].append(0)
                    self.data["cpu_info"][cpu_id]["usage"] = []

    def _calculate_diff_total(self, cpu_id, index):
        diff_total = int(self.data["cpu_data"][cpu_id]["total"][index])\
            - int(self.data["cpu_data"][cpu_id]["total"][index - 1])
        diff_total = diff_total if diff_total > 0 else 0.001
        return diff_total

    def _prepare_usage_cpu_info(self, cpu_id, diff_total, index):
        for cpu_key in self.data["cpu_data"][cpu_id]:
            if cpu_key != "total":
                diff = int(self.data["cpu_data"][cpu_id][cpu_key][index])\
                    - int(self.data["cpu_data"][cpu_id][cpu_key][index - 1])
                diff_tmp = int(round(100 * (diff_total - diff) / diff_total))
                self.data["cpu_info"][cpu_id][cpu_key].append(100 - diff_tmp)
        idle_data = int(self.data["cpu_info"][cpu_id]["idle"][index])
        self.data["cpu_info"][cpu_id]["usage"].append(100 - idle_data)

    def _prepare_meminfo_json_format(self):
        for meminfo_param in self.data["meminfo"].keys():
            values = []
            for index, timestamp in enumerate(self.data["systime"]):
                values.append({"x": timestamp, "y": self.data["meminfo"][meminfo_param][index - 1]})
            self.json_data["meminfo_json_format"].append({"key": meminfo_param, "values": values})

    def _prepare_diskspaceinfo_json_format(self):
        for diskspace_param in self.data['diskspace'].keys():
            values = []
            for index, timestamp in enumerate(self.data["systime"]):
                if diskspace_param != "Mounted":
                    values.append({"x": timestamp, "y": self.data["diskspace"][diskspace_param]['Used'][index]})
            self.json_data["diskspace_used_json_format"].append({"key": diskspace_param, "values": values})

    def _prepare_interrupts_json_format(self):
        for interrupt_param in self.data['interrupts'].keys():
            self.json_data["interrupts_json_format"].update({interrupt_param: []})
            for cpu in self.cpu_cores:
                values = []
                for index, timestamp in enumerate(self.data["systime"]):
                    values.append({"x": timestamp, "y": self.data["interrupts"][interrupt_param][cpu][index]})
                self.json_data["interrupts_json_format"][interrupt_param].append({"key": cpu, "values": values})

    def _prepare_general_proc_usage_json_format(self):
        for cpu_id in self.data['cpu_info'].keys():
            values = []
            for index, timestamp in enumerate(self.data["systime"][1:len(self.data["cpu_info"][cpu_id]['usage'])]):
                values.append({"x": timestamp, "y": self.data["cpu_info"][cpu_id]['usage'][index]})
            self.json_data["cpu_load_general_view_json_format"].append({"key": cpu_id, "values": values})

    def _prepare_cpu_info_details_json_format(self):
        for task in self.data['cpu_info']['total'].keys():
            values = []
            if task == "usage" or task == "total":
                continue
            for index, timestamp in enumerate(self.data["systime"][1:len(self.data["cpu_info"]["total"]['usage'])]):
                values.append({"x": timestamp, "y": self.data["cpu_info"]['total'][task][index]})
            self.json_data["cpu_info_details_json_format"].append({"key": task, "values": values})

    def _prepare_benchmark_processor_load(self):
        for cpu_core in self.data['cpu_info']:
            if cpu_core not in self.json_data['cpu_info_overall_json_format']:
                self.json_data['cpu_info_overall_json_format'][cpu_core] = {"min_value": 0, "max_value": 0, "value": 0}
            if cpu_core in self.json_data['cpu_info_overall_json_format']:
                try:
                    self.json_data['cpu_info_overall_json_format'][cpu_core]['min_value'] = int(min(
                        list(map(int, self.data['cpu_info'][cpu_core]['usage']))))
                    self.json_data['cpu_info_overall_json_format'][cpu_core]['max_value'] = int(max(
                        list(map(int, self.data['cpu_info'][cpu_core]['usage']))))
                    self.json_data['cpu_info_overall_json_format'][cpu_core]['value'] = \
                        int(sum(self.data['cpu_info'][cpu_core]['usage']) / len(self.data['cpu_info'][cpu_core]['usage']))
                except ValueError as exception:
                    MolerTest.warning(msg=exception)

    def _prepare_cpu_usage_info(self):
        self._prepare_diff_total()
        self._prepare_general_proc_usage_json_format()
        self._prepare_cpu_info_details_json_format()
        self._prepare_benchmark_processor_load()


"""
procdump_parser = ProcdumpParser(procdump_dir="./procump_asik_master").parse()
"""
